def histogram_differences(adapters: List[int]) -> HistogramOfDeltas:
    """Compute the histogram of jolt differences in ``adapters``."""
    histo = collections.defaultdict(lambda: 0)  # type: MutableMapping[int, int]

    for prev, current in common.pairwise(sorted([0] + adapters + [max(adapters) + 3])):
        delta = current - prev
        histo[delta] += 1

    return HistogramOfDeltas(histo)

def apply(layout: Layout) -> Tuple[Layout, int]:
    """
    Compute a single iteration.

    :return: (new layout, number of changes)"""
    new_table = [["" for _ in range(layout.width)] for _ in range(layout.height)]

    change_count = 0

    for i in range(layout.height):
        for j in range(layout.width):
            state = layout.table[i][j]

            if state == ".":
                new_state = "."
            else:
                occupied = 0
                neighbourhood = list_neighbourhood(
                    i=i, j=j, height=layout.height, width=layout.width
                )
                for neighbour_i, neighbour_j in neighbourhood:
                    if layout.table[neighbour_i][neighbour_j] == "#":
                        occupied += 1

                if state == "L" and occupied == 0:
                    new_state = "#"
                    change_count += 1
                elif state == "#" and occupied >= 4:
                    new_state = "L"
                    change_count += 1
                else:
                    new_state = state

            new_table[i][j] = new_state

    return Layout(table=new_table), change_count

def parse_layout(lines: List[str]) -> Layout:
    """Parse the initial layout given as ``lines``."""
    table = []  # type: List[List[str]]
    for line in lines:
        row = []  # type: List[str]
        for symbol in line:
            row.append(symbol)

        table.append(row)

    return Layout(table=table)

def parse_input(puzzle_input: str) -> Lines:
    """Split the puzzle input along the newlines."""
    return Lines(puzzle_input.splitlines())

def next_departure(bus_id: int, min_time: int) -> int:
    """Compute the next departure of ``bus_id`` leaving earliest at ``min_time``."""
    missed_last_bus_by = min_time % bus_id
    if missed_last_bus_by == 0:
        return min_time
    else:
        return min_time - missed_last_bus_by + bus_id

def find_departure(start_time: int, bus_ids: Set[int]) -> Tuple[int, int]:
    """Find the earliest bus to catch after ``start_time``."""
    return min([(next_departure(bid, start_time), bid) for bid in bus_ids])

def parse_mask(text: str) -> Mask:
    """Parse the text as an clearing and a setting mask, respectively."""
    mtch = MASK_RE.match(text)
    assert mtch is not None

    mask_text = mtch.group("mask")
    assert len(mask_text) == 36

    setting = 0
    clearing = 2**36 - 1

    # Loop from the least significant bit
    for bit_i in range(len(mask_text)):
        symbol = mask_text[-bit_i - 1]
        if symbol == "0":
            clearing = clearing ^ (1 << bit_i)
        elif symbol == "1":
            setting = setting | (1 << bit_i)
        elif symbol == "X":
            pass
        else:
            raise NotImplementedError(f"{symbol=}")

    return Mask(clearing=clearing, setting=setting)

def sum_memory(memory: Memory) -> int:
    """Sum the values in the memory slots."""
    return sum(memory.slots.values())

def solve(starting_numbers: List[int]) -> int:
    """Play the memory game starting with the ``starting_numbers`` to``LAST_STEP``."""
    d: Dict[int, int] = dict()
    last = starting_numbers[0]
    for index, number in enumerate(starting_numbers[1:]):
        d[last] = index + 1
        last = number

    for step in range(len(starting_numbers), LAST_STEP):
        if last not in d:
            d[last] = step
            last = 0
        else:
            difference = step - d[last]
            d[last] = step
            last = difference
    return last

def invalid_fields(rules: List[Rule], ticket: List[int]) -> List[int]:
    """Select the invalid fields from a ``ticket`` according to ``rules``."""
    result = []  # type: List[int]
    for value in ticket:
        if not any(applies(rule=rule, value=value) for rule in rules):
            result.append(value)

    return result

def list_all_invalid_values(rules: List[Rule], tickets: List[List[int]]) -> List[int]:
    """Select the invalid fields accross all ``tickets`` according to ``rules``."""
    result = []  # type: List[int]

    for ticket in tickets:
        for value in ticket:
            if not any(applies(rule=rule, value=value) for rule in rules):
                result.append(value)

    return result

def list_neighbourhood(point: Point) -> List[Point]:
    """List all neighbouring cubes w.r.t. the ``point`` cube."""
    result = []  # type: List[Point]
    for x in [point[0] - 1, point[0], point[0] + 1]:
        for y in [point[1] - 1, point[1], point[1] + 1]:
            for z in [point[2] - 1, point[2], point[2] + 1]:
                neighbour = Point(x=x, y=y, z=z)
                if neighbour != point:
                    result.append(neighbour)

    return result

def parse_initial(lines: Lines) -> Activity:
    """Parse ``lines`` into the state of the energy source."""
    result = set()  # type: Set[Point]

    z = 0
    for y, line in enumerate(lines):
        for x, symbol in enumerate(line):
            if symbol == '#':
                result.add(Point(x, y, z))

    return Activity(result)

def count_active(activity: Activity) -> int:
    """Count number of active cells in the ``activity``."""
    return len(activity)

def extract_expression(expr: str) -> str:
    """Extract the sub-expression surrounded by parentheses in ``expr``."""
    parenthesis_balance = 0
    result = ""

    for c in expr:
        if c == "(":
            parenthesis_balance += 1
        elif c == ")":
            parenthesis_balance -= 1

        if parenthesis_balance == 0:
            return result[1:]
        else:
            result += c
    raise Exception("I should never end up here!")

def serialize(node: Node) -> str:
    """Serialize the abstraction syntax tree given as ``node`` to a string."""
    result = ""
    if isinstance(node.head, int):
        result += str(node.head)
    else:
        result += "({})".format(serialize(node.head))

    if node.tail:
        for tail in node.tail:
            if isinstance(tail.right, int):
                result += "{}{}".format(tail.op.value, tail.right)
            else:
                result += "{}({})".format(tail.op.value, serialize(tail.right))

    return result

def match(self, text: str) -> Optional[str]:
        """Check whether ``text`` matches exactly the :py:attr:`literal`."""
        if not text.startswith(self.literal):
            return None

        return text[len(self.literal) :]

def count_matching_messages(rule_0: Rule, messages: List[str]) -> int:
    """Count the ``messages`` that match the rules starting from ``rule_0``."""
    result = 0
    for message in messages:
        remaining_suffix = rule_0.match(message)
        if remaining_suffix is not None and len(remaining_suffix) == 0:
            result += 1

    return result

def find_pair_with_sum(items: List[int], total: int) -> Optional[Tuple[int, int]]:
    """Find the two entries that sum to ``total``."""
    for i, x in enumerate(items):
        for y in items[i + 1 :]:
            if x + y == total:
                return (x, y)
    return None

def reverse_side(side: str) -> str:
    """Flip the side."""
    return "".join(reversed(side))

def serialize_entry(entry: Entry) -> IngredientLine:
    """Serialize the ``entry`` back into the string."""
    ingredients_str = " ".join(ingredient for ingredient in entry.ingredients)
    allergens_str = ", ".join(allergen for allergen in entry.allergens)

    return IngredientLine(f"{ingredients_str} (contains {allergens_str})")

def compute_score(deck: Deck) -> int:
    """Compute the score for the given deck based on its cards."""
    score = 0
    for i, card in enumerate(deck):
        score += (len(deck) - i) * card

    return score

def play(split: Split) -> Split:
    """Play the game starting with the ``split`` until one of the players wins."""
    while True:
        split = play_a_round(split=split)

        if len(split.deck1) == 0 or len(split.deck2) == 0:
            break

    return split

def cup_circle_to_str(cup_circle: CupCircle) -> str:
    """Stringify the labels of the ``cup_circle``, starting from the current cup."""
    result: List[str] = []
    if cup_circle.current_cup:
        tmp = cup_circle.current_cup
        result += str(tmp.label)
        while tmp.next_cup != cup_circle.current_cup:
            tmp = tmp.next_cup
            result += str(tmp.label)
    return "".join(result)

def initialize_cups(cup_labels: str) -> CupCircle:
    """Create a CupCircle from ``cup_labels``."""
    cup_circle = CupCircle()
    for label in cup_labels:
        cup_circle.add_new_cup(int(label))
    return cup_circle

def crab_move(cup_circle: CupCircle) -> None:
    """Perform one move by the crab."""
    if not cup_circle.current_cup:
        raise Exception("the cup circle is empty")
    # 1. remove 3 cups clockwise from current cup
    removed_cups_head = cup_circle.current_cup.next_cup
    for _ in range(3):
        cup_circle.current_cup.next_cup = cup_circle.current_cup.next_cup.next_cup
    # 2. find destination cup
    destination_cup = None
    tmp = cup_circle.current_cup.next_cup
    while tmp != cup_circle.current_cup:
        if tmp.label < cup_circle.current_cup.label:
            if not destination_cup:
                destination_cup = tmp
            elif tmp.label > destination_cup.label:
                destination_cup = tmp
        tmp = tmp.next_cup
    if not destination_cup:
        tmp = cup_circle.current_cup.next_cup
        while tmp != cup_circle.current_cup:
            if not destination_cup:
                destination_cup = tmp
            elif tmp.label > destination_cup.label:
                destination_cup = tmp
            tmp = tmp.next_cup
        assert destination_cup
    # 3. place cups back
    removed_cups_head.next_cup.next_cup.next_cup = destination_cup.next_cup
    destination_cup.next_cup = removed_cups_head
    cup_circle.current_cup = cup_circle.current_cup.next_cup

def solve_100_steps(cup_labels: str) -> CupCircle:
    """Solve the problem for 100 crab moves."""
    cup_circle = initialize_cups(cup_labels)
    for _ in range(100):
        crab_move(cup_circle)
    return cup_circle

def parse_line(line: str) -> List[Direction]:
    """Parse the input line."""
    if len(line) == 0:
        return []

    directions = []  # type: List[Direction]
    for part in ONE_DIRECTION_RE.findall(line):
        direction = VALUE_TO_DIRECTION[part]
        directions.append(direction)

    return directions

def stringify_directions(directions: List[Direction]) -> str:
    """Represent the directions as a concatenated text."""
    return "".join(direction.value for direction in directions)

def parse_input(lines: Sequence[InputLine]) -> Tuple[int, int, str]:
    """Parse the input map given as ``lines``."""
    width: int = len(lines[0])
    height: int = len(lines)
    return width, height, "".join(lines)

def count_valid(batch: str) -> int:
    """Count the number of valid passports in the ``batch``."""
    return sum(
        1
        for passport_text in blank_line_split(batch)
        if is_valid(parse_passport_entries(passport_text))
    )

def apply(first: int, last: int, directive: str) -> Tuple[int, int]:
    """
    Apply the ``directive`` given the range as ``[first, last]`` (inclusive).

    :return: new first, new last
    """
    half = int((last - first + 1) / 2)

    if directive in "FL":
        return first, last - half

    elif directive in "BR":
        return first + half, last

    else:
        raise NotImplementedError(directive)

def determine_id(row: int, column: int) -> int:
    """Compute the identifier of the seat given its ``row`` and ``column``."""
    return row * 8 + column

def solve(input_string: str) -> int:
    """Count the number of yes answers in the group given as ``input_string``."""
    count = 0
    yes_answers: Set[str] = set()
    for line in input_string.split("\n"):
        if line:
            yes_answers = yes_answers.union(list(line))
        else:
            count += len(yes_answers)
            yes_answers.clear()
    count += len(yes_answers)
    return count

def containers(kind: str, rules: Rules) -> Set[str]:
    """Compute the set of known containers."""
    known_containers: Set[str] = {kind}
    last_size = 0
    while last_size < len(known_containers):
        last_size = len(known_containers)
        for container_kind, subbags in rules.items():
            for (contents_kind, _ct) in subbags.items():
                if contents_kind in known_containers:
                    known_containers.add(container_kind)
    return known_containers

def parse(lines: Lines) -> List[Instruction]:
    """Parse the boot code given as ``lines``."""
    return [parse_line(line) for line in lines]

def solve(puzzle_input: List[int], preamble_length: int) -> Optional[Tuple[int, int]]:
    """
    Parse the data of the XMAS protocol, ``puzzle_input``, and find a weakness.

    :return:
        offset of the number,
        first number *after* the preamble which uncovers the weakness
    """
    for index, number in enumerate(puzzle_input[preamble_length:]):
        preamble = puzzle_input[index : index + preamble_length]
        valid = False
        for i in preamble:
            for j in preamble:
                if i != j and i + j == number:
                    valid = True
        if not valid:
            return preamble_length + index, number

    return None

def draw(width: int, height: int) -> Lines:
    """Draw the pattern of the size ``width`` x ``height`` and return the text lines."""
    result = []  # type: List[str]

    vertical_pad = int(height / 5) - 1

    result.append("-" * width)

    for _ in range(vertical_pad):
        result.append("".join(["|", " " * (width - 2), "|"]))

    def draw_cross(cross_count: int) -> None:
        space_count = int((width - cross_count - 2) / 2)
        for _ in range(int(height / 5)):
            result.append(
                "".join(
                    ["|", " " * space_count, "+" * cross_count, " " * space_count, "|"]
                )
            )

    draw_cross(cross_count=int(width / 5))
    draw_cross(cross_count=3 * int(width / 5))
    draw_cross(cross_count=int(width / 5))

    for _ in range(vertical_pad):
        result.append("".join(["|", " " * (width - 2), "|"]))

    result.append("-" * width)

    return Lines(result)

def draw(width: int) -> Lines:
    """Draw the pattern with the size given as ``width`` and return the text lines."""
    result = []  # type: List[str]

    for i in range(1, int(width / 2) + 1):
        if i % 2 == 1:
            pattern = "**.."
        else:
            pattern = "..**"

        result.append(pattern * int(width / 4))

    return Lines(result)

def draw(height: int) -> Lines:
    """Draw the pattern of size given as ``height`` and return the text lines."""
    if height == 1:
        return Lines(["1"])

    result = []  # type: List[str]

    middle = int(height / 2)
    for i in range(1, height + 1):
        if i < middle:
            digit_count = 1 + 2 * (i - 1)
        elif i == middle:
            digit_count = height
        else:
            digit_count = 1 + 2 * (height - i)
        pad = int((height - digit_count) / 2)

        line = "".join(["." * pad, str(i) * digit_count, "." * pad])
        result.append(line)

    return Lines(result)

def repr_binary(n: int) -> str:
    """Represent ``n`` as a binary number."""
    digits = []  # type: List[str]
    remaining = n

    while remaining > 0:
        digits.append(str(remaining % 2))
        remaining = remaining // 2

    return "0b" + "".join(reversed(digits))

def gcd(x: int, y: int) -> int:
    """Compute the greatest common divisor (GCD) between ``x`` and ``y``."""
    if x >= y and x % y == 0:
        return y

    return gcd(y, x % y)

def encode(number: int) -> str:
    """Encode the given ``number`` as segments identifiers of the LED display."""
    return FROM_NUMBER[number]

def compute_stats(measurements: List[Measurement]) -> Tuple[float, float, float]:
    """
    Compute the statistics of the given ``measurements``.

    :return: Minimum, mean, maximum
    """
    return min(measurements), statistics.mean(measurements), max(measurements)

def bin_index(ranges: BinRanges, value: float) -> int:
    """Find the index of the bin range among ``ranges`` corresponding to ``value``."""
    # Edge cases
    if value < ranges[0].start:
        return -1

    if value >= ranges[-1].end:
        return -1

    if len(ranges) == 1:
        if ranges[0].start <= value < ranges[0].end:
            return 0
        else:
            return -1

    # Binary search
    first = 0
    last = len(ranges) - 1

    width = last - first + 1

    while True:
        # Cover the edge cases which are often coded wrong
        if width <= 2:
            if ranges[first].start <= value < ranges[first].end:
                return first

            return last

        middle = first + width // 2
        if ranges[middle].start <= value < ranges[middle].end:
            return middle

        elif value < ranges[middle].start:
            last = middle - 1

        elif value >= ranges[middle].end:
            first = middle + 1

        else:
            raise AssertionError("Unexpected branch")

        old_width = width
        width = last - first + 1
        assert width < old_width, "Loop invariant: the index range is getting smaller"

def duration(self) -> int:
        """Compute the duration of the stay."""
        return self.end - self.start + 1

def most_booked_room(entries: List[Entry]) -> int:
    """Find the number of the most booked room in the ``entries``."""
    histo = collections.defaultdict(lambda: 0)  # type: MutableMapping[int, int]
    for entry in entries:
        histo[entry.room_number] += 1

    return max(histo, key=lambda key: histo[key])

def longest_booked_room(entries: Collection[Entry]) -> int:
    """
    Find the room booked for the longest accumulated time according to ``entries``.
    """
    histo = collections.defaultdict(lambda: 0)  # type: MutableMapping[int, int]
    for entry in entries:
        histo[entry.room_number] += entry.duration()

    return max(histo, key=lambda key: histo[key])

def room_with_most_revenue(entries: Collection[Entry]) -> int:
    """Find the room which brought in the most revenue according to ``entries``."""
    histo = collections.defaultdict(lambda: 0)  # type: MutableMapping[int, float]
    for entry in entries:
        histo[entry.room_number] += (
            entry.duration() * entry.price_per_day * entry.price_discount
        )

    return max(histo, key=lambda key: histo[key])

def total_revenue(entries: Collection[Entry]) -> float:
    """Compute the total revenue of the hotel based on ``entries``."""
    return sum(
        entry.duration() * entry.price_per_day * entry.price_discount
        for entry in entries
    )

def add_first(self, value: int) -> None:
        """Prepend the ``value`` to the list."""
        if self._first is None:
            self._first = Node(value=value, next_node=None)
            self._last = self._first
        else:
            self._first = Node(value=value, next_node=self._first)

        self._count += 1

def remove_first(self) -> int:
        """Remove first element of the list."""
        cur = Cursor(linked_list=self)
        return cur.remove()

def remove_last(self) -> int:
        """Remove the last element of the list."""
        cur = Cursor(linked_list=self)
        while not cur.is_last():
            cur.move()

        return cur.remove()

def get(self, index: int) -> int:
        """Retrieve the ``index``-th element of the list."""
        cur = Cursor(linked_list=self)
        for _ in range(index):
            cur.move()

        return cur.value()

def set(self, index: int, value: int) -> None:
        """Set the ``index``-th element to ``value``."""
        cur = Cursor(linked_list=self)
        for _ in range(index):
            cur.move()

        cur.set_value(value)

def list_subsequences(text: str, length: int) -> Set[str]:
    """
    List all subsequences of size ``length`` in ``text``.

    >>> sorted(list_subsequences("apple", 2))
    ['ae', 'al', 'ap', 'le', 'pe', 'pl', 'pp']
    """
    if length == 0:
        return set()

    if length == len(text):
        return {text}

    result = set()  # type: Set[str]
    for substring_indices in itertools.combinations(range(len(text)), length):
        substring = "".join(text[index] for index in substring_indices)
        result.add(substring)

    return result

def simulate(specs: Specs, steps: int) -> Stats:
    """Simulate in ``steps`` number of iterations according to the ``specs``."""
    finished = 0

    # Length of the queues at each step
    queues = [[] for _ in specs.checkout_efficiencies]  # type: List[List[Customer]]

    # The length of all the queues at each step
    queue_lengths = [[] for _ in specs.checkout_efficiencies]  # type: List[List[int]]

    for _ in range(steps):
        # Process an item
        for queue, efficiency in zip(queues, specs.checkout_efficiencies):
            if len(queue) > 0:
                customer = queue[0]
                assert customer.items_in_cart > 0

                if random.random() < efficiency:
                    customer.items_in_cart -= 1
                    if customer.items_in_cart == 0:
                        queue.pop(0)
                        finished += 1

        # Enter new customer
        if random.random() < specs.new_customer_probability:
            queue_index = random.randint(0, len(queues) - 1)
            queues[queue_index].append(
                Customer(items_in_cart=random.randint(1, specs.max_cart_size))
            )

        # Compute stats for the step
        for queue, lengths in zip(queues, queue_lengths):
            lengths.append(len(queue))

    # fmt: off
    assert len(queue_lengths) == len(specs.checkout_efficiencies)
    assert all(
        len(entry) == steps
        for entry in queue_lengths
    ), f"{steps=}, {len(queue_lengths)=}, {[len(entry) for entry in queue_lengths]=}"
    # fmt: on

    return Stats(
        finished=finished,
        avg_queue_lengths=[statistics.mean(lengths) for lengths in queue_lengths],
        max_queue_lengths=[max(lengths) for lengths in queue_lengths],
    )

def list_next_positions(pos: Position) -> Sequence[Position]:
    """List all the possible next positions based on the current position ``pos``."""
    return (
        Position(x=pos.x + 1, y=pos.y),
        Position(x=pos.x, y=pos.y + 1),
        Position(x=pos.x - 1, y=pos.y),
        Position(x=pos.x, y=pos.y - 1),
    )

def parse_block(lines: Lines) -> Block:
    """Parse the given block of the input data given as text ``lines``."""
    name = lines[0]
    flights = []  # type: List[Flight]

    for line in lines[1:]:
        mtch = FLIGHT_RE.match(line)
        assert mtch

        flights.append(
            Flight(
                number=mtch.group("number"),
                date=datetime.datetime.strptime(mtch.group("date"), "%d.%m.%Y").date(),
                class_of_flight=STR_TO_CLASS_OF_FLIGHT[mtch.group("class_of_flight")],
                miles=None if mtch.group("miles") is None else int(mtch.group("miles")),
            )
        )

    return Block(name=name, flights=flights)

def parse(lines: Lines) -> List[Block]:
    """Parse the input data given as text ``lines`` into structured blocks."""
    list_of_block_lines = []  # type: List[Lines]

    accumulator = []  # type: List[str]
    for line in lines:
        if line == ".":
            if accumulator:
                list_of_block_lines.append(Lines(accumulator))
                accumulator = []
        else:
            accumulator.append(line)

    if accumulator:
        raise ValueError(
            "Unexpected unfinished block: {}".format("\n".join(accumulator))
        )

    return [parse_block(lines=block_lines) for block_lines in list_of_block_lines]

def compute_totals(blocks: List[Block]) -> MutableMapping[str, int]:
    """
    Compute the total miles collected by the flier.

    :return: Flier name 🠒 miles collected
    """
    result = dict()  # type: MutableMapping[str, int]

    for block in blocks:
        if block.name not in result:
            result[block.name] = 0

        for flight in block.flights:
            if flight.class_of_flight == ClassOfFlight.ECONOMY:
                result[block.name] += flight.miles
            elif flight.class_of_flight == ClassOfFlight.BUSINESS:
                result[block.name] += flight.miles * 2
            elif flight.class_of_flight == ClassOfFlight.FIRST:
                result[block.name] += flight.miles * 3
            else:
                raise NotImplementedError(flight.class_of_flight)

    return result

def sum_grades(self) -> Decimal:
        """Sum all grades of the student."""
        return self.grade1 + self.grade2 + self.grade3

def top(gradings: List[Grading], limit: int) -> List[Grading]:
    """Find the top ``limit`` students among the ``gradings``."""
